126	    default Integer formatMembershipPoints(Owner owner) {
127	        if (owner == null) {
128	            return null;
129	        }
130	        int points = 0;
131	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
132	        if (hasEmail) {
