178	     */
179	    default Integer formatCheckDigit(Owner owner) {
180	        if (owner == null || owner.getCustomerCode() == null) {
181	            return null;
182	        }
183	        String code = owner.getCustomerCode();
184	        int sum = 0;
185	        boolean dbl = true;
186	        for (int i = code.length() - 1; i >= 0; i--) {
187	            char c = code.charAt(i);
188	            if (c < '0' || c > '9') {
