208	     * the number cannot be derived without both.
209	     */
210	    default String formatMembershipNumber(Owner owner) {
211	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
212	            return null;
213	        }
214	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
